cat > /private/tmp/claude-501/-Users-trang-doan-Desktop-code-discourse-graph/1f1355de-28df-4625-a275-2807a4d24325/scratchpad/semantic-order-proof.mjs <<'EOF'
// Drives the semantic path with a stub whose returned order deliberately
// disagrees with score order, proving the UI keeps the provider's order.
const QUERY = "discourse";

export default {
  async ready({ page }) {
    return page.evaluate(() => Boolean(window.roamAlphaAPI?.data?.async));
  },

  async run({ page }) {
    const discovery = await page.evaluate(() => {
      const rows = window.roamAlphaAPI.q(
        "[:find ?uid ?title :where [?p :node/title ?title] [?p :block/uid ?uid]]",
      );
      const discourse = rows
        .filter(([, title]) => /^\[\[[A-Z]{2,4}\]\] - .+/.test(title))
        .sort((a, b) => a[1].localeCompare(b[1]))
        .slice(0, 6)
        .map(([uid, title]) => ({ uid, title }));
      return { totalPages: rows.length, picked: discourse };
    });

    if (discovery.picked.length < 5) {
      return { skipped: "fewer than 5 discourse node pages in graph", discovery };
    }

    // Returned order is index order; scores are deliberately NOT descending.
    const scores = [0.11, 0.97, 0.42, 0.88, 0.35, 0.76].slice(
      0,
      discovery.picked.length,
    );
    const stubHits = discovery.picked.map((p, i) => ({
      uid: p.uid,
      title: p.title,
      score: scores[i],
      type: "page",
    }));

    await page.evaluate((hits) => {
      const api = window.roamAlphaAPI;
      window.__dgProof = {
        origEnabled: api.data.semanticSearchEnabled,
        origSearch: api.data.async.semanticSearch,
        calls: 0,
      };
      api.data.semanticSearchEnabled = () => true;
      api.data.async.semanticSearch = async () => {
        window.__dgProof.calls += 1;
        return hits;
      };
    }, stubHits);

    await page.keyboard.press("Meta+p");
    await page.waitForTimeout(600);
    await page.keyboard.type("Open Node Search", { delay: 25 });
    await page.waitForTimeout(800);
    await page.keyboard.press("Enter");

    const input = page.locator('input[placeholder="Search discourse nodes..."]');
    await input.waitFor({ timeout: 20000 });
    await input.click();
    await input.type(QUERY, { delay: 40 });

    const listbox = page.locator('[aria-label="Search results"][role="listbox"]');
    await listbox.waitFor({ timeout: 20000 });
    await page.waitForTimeout(2500);

    const domOrder = await listbox
      .locator('[role="option"]')
      .allInnerTexts();

    const calls = await page.evaluate(() => window.__dgProof.calls);

    const strip = (t) => t.replace(/^\[\[[A-Z]{2,4}\]\] - /, "").trim();
    const providerOrder = discovery.picked.map((p) => strip(p.title));
    const scoreDescOrder = discovery.picked
      .map((p, i) => ({ t: strip(p.title), s: scores[i] }))
      .sort((a, b) => b.s - a.s)
      .map((x) => x.t);

    const domTitles = domOrder.map((t) =>
      t.split("\n").pop().trim(),
    );

    const matchesProvider =
      JSON.stringify(domTitles) === JSON.stringify(providerOrder);
    const matchesScoreDesc =
      JSON.stringify(domTitles) === JSON.stringify(scoreDescOrder);

    return {
      semanticStubCalls: calls,
      providerOrder,
      scoreDescOrder,
      domTitles,
      ordersAreDistinguishable:
        JSON.stringify(providerOrder) !== JSON.stringify(scoreDescOrder),
      matchesProvider,
      matchesScoreDesc,
      assertion:
        matchesProvider && !matchesScoreDesc ? "PASS" : "FAIL",
    };
  },

  async cleanup({ page }) {
    await page.evaluate(() => {
      const p = window.__dgProof;
      if (!p) return;
      window.roamAlphaAPI.data.semanticSearchEnabled = p.origEnabled;
      window.roamAlphaAPI.data.async.semanticSearch = p.origSearch;
      delete window.__dgProof;
    });
  },
};
EOF
