cat > /private/tmp/claude-501/-Users-trang-doan-Desktop-code-discourse-graph/1f1355de-28df-4625-a275-2807a4d24325/scratchpad/graph-sweep.mjs <<'EOF'
const GRAPHS = [
  "discourse-dev-graph",
  "plugin-testing-discourse-graphs",
  "plugin-testing-megacoglab",
  "template-lab",
  "tldraw-real-time-sync",
  "plugin-testing-akamatsulab",
  "plugin-testing-akamatsulab2",
  "discourse-graphs",
  "megacoglab",
  "akamatsulab",
];

export default {
  async ready({ page }) {
    return page.evaluate(() => Boolean(window.roamAlphaAPI?.data));
  },
  async run({ page }) {
    const results = {};
    for (const g of GRAPHS) {
      try {
        await page.goto(`https://roamresearch.com/#/app/${g}`, {
          waitUntil: "domcontentloaded",
          timeout: 30000,
        });
        const value = await page.waitForFunction(
          (name) => {
            const api = window.roamAlphaAPI;
            if (!api?.data?.semanticSearchEnabled || api.graph?.name !== name) {
              return null;
            }
            try {
              return {
                enabled: api.data.semanticSearchEnabled(),
                type: api.graph.type,
                encrypted: Boolean(api.graph.isEncrypted),
              };
            } catch (e) {
              return { error: String(e) };
            }
          },
          g,
          { timeout: 75000, polling: 1000 },
        );
        results[g] = await value.jsonValue();
      } catch (e) {
        results[g] = { error: String(e).split("\n")[0].slice(0, 160) };
      }
    }
    const enabled = Object.entries(results)
      .filter(([, v]) => v && v.enabled === true)
      .map(([k]) => k);
    return { results, graphsWithSemanticSearch: enabled };
  },
};
EOF
